/* global console, process */
import { readFileSync, writeFileSync } from 'node:fs';

const sourcePath = 'packages/equipment-catalog/catalog.json';
const outputPath = 'packages/server/src/generatedEquipmentCatalog.ts';
const catalog = JSON.parse(readFileSync(sourcePath, 'utf8'));
const output = `// Generated from ${sourcePath} by scripts/generate-equipment-catalog.mjs.
// Do not edit this file directly.
interface EquipmentDefinition {
  slot: 'Pickaxe' | 'Shield' | 'Beacon' | 'CPU' | 'RAM';
  efficiency?: number;
  computeCost?: number;
  computePoints?: number;
  capacityBonus?: number;
}

export const EQUIPMENT_CATALOG: Readonly<Record<string, Readonly<EquipmentDefinition>>> = ${JSON.stringify(catalog, null, 2)};

export function getEquipmentDefinition(itemType: string) {
  return EQUIPMENT_CATALOG[itemType];
}
`;

if (process.argv.includes('--check')) {
  if (readFileSync(outputPath, 'utf8') !== output) {
    console.error(`${outputPath} is stale; run node scripts/generate-equipment-catalog.mjs`);
    process.exit(1);
  }
} else {
  writeFileSync(outputPath, output);
}
